p='03-manuscript/arc-01/ch-02.md'
t=open(p,encoding='utf-8').read(); n=0
def rep(a,b):
    global t,n
    assert t.count(a)==1,(t.count(a),a[:70]); t=t.replace(a,b); n+=1
R=[
("Меня это почему-то успокоило: человек, который считает дни чужого светильника, устроен не так плохо.","Меня это почему-то успокоило."),
("Лезвие такого следа не оставляет. Такое остаётся, когда рвёт плоть.","Лезвие такого следа не оставляет."),
("Всё остальное я о нём придумала сама, из того же материала, из которого придумывают про соседей.","Всё остальное я о нём придумала сама."),
("Стул был жёсткий, с прямой спинкой, из тех, на которых нельзя устроиться удобно, и это, наверное, было нарочно.","Стул был жёсткий, с прямой спинкой, из тех, на которых нельзя устроиться удобно."),
("— Ничего вам пока не понятно. — Он не нажимал; так поправляют счёт. — Что такое разрешение по существу?","— Ничего вам пока не понятно. Что такое разрешение по существу?"),
("Я слушала и ловила себя на том, что уже считаю.\n\nОн говорил про советника и карету, а у меня в голове уже раскладывалось: закрытая карета, значит, кучер; остановка по дороге, значит, место известное; забрали ночью, значит, ждали. И где-то на краю этого счёта сидела мысль про человека, который остановился ночью в месте, о котором предпочёл умолчать. Такие места посещают не по одному разу.\n\nСчитать было рано. Мне ещё ничего не предложили.",
 "Он говорил про советника и карету, а у меня в голове уже раскладывалось: закрытая карета, значит, кучер; остановка по дороге, значит, место известное; забрали ночью, значит, ждали."),
("Инструктор постоял, поглядел на связку в кулаке, как будто среди этих ключей мог найтись нужный, и вышел, и ключи звякнули уже за дверью.","Инструктор постоял, поглядел на связку в кулаке, как будто среди этих ключей мог найтись нужный, и вышел. Ключи звякнули уже за дверью."),
("Тёплая пыль, чернила, немного шерсти — и поверх всего этого чужая уверенность, что я соглашусь.","Тёплая пыль, чернила, немного шерсти."),
("Сделалось холодно в кистях рук, как перед зачётом по бегу, и я вспомнила, когда у меня так бывает: перед тем, как согласиться.","Сделалось холодно в кистях рук, как перед зачётом по бегу."),
("Самое неприятное было в том, что он не смягчал. Он мог сказать «этого не случится», мог пообещать, что вытащит, мог хотя бы понизить голос. Тогда мне было бы с чем спорить.","Он не смягчал. Мог сказать «этого не случится», мог понизить голос. Тогда мне было бы с чем спорить."),
("Передо мной лежали стопки тетрадей, а в голове было пусто и очень ясно: решение уже есть, а формулировки ещё нет.","Передо мной лежали стопки тетрадей, а в голове было пусто и очень ясно."),
("А через год я стояла бы у Хельги за стойкой и помнила, где уксус.\n\nЭто была нечестная мысль. Работа у Хельги — хорошая работа, и я знала это лучше многих. Но училась я не для того, чтобы вернуться туда, откуда уходила.",
 "А через год я стояла бы у Хельги за стойкой и помнила, где уксус."),
("Он открыл тетрадь и стал читать. Разговор был окончен.","Он открыл тетрадь и стал читать."),
("Рыцаря не посылают за бумагами. Рыцарь и есть бумага: где он появился, там дело уже стало официальным.","Рыцаря за бумагами не посылают. Где он появился, там дело уже официальное."),
("Я об этом не думала никогда.\n\nЯ привыкла считать, что Северин просто выше нас всех и потому существует отдельно. Оказалось, что он отдельно ещё и потому, что его нельзя применить тихо.","Я об этом не думала никогда."),
("Хельга такие печёт с утра и к вечеру не греет, потому что, по её словам, греть — это признавать, что не продала. Я съела","Хельга такие печёт с утра и к вечеру не греет. Я съела"),
("Кто-то из старших тащил через двор ведро, и вода плескала ему на сапог, и он через каждые пять шагов перекладывал ручку в другую руку.","Кто-то из старших тащил через двор ведро, вода плескала ему на сапог, и через каждые пять шагов он перекладывал ручку в другую руку."),
("Я хотела спросить, зачем он вообще остался, и не спросила, потому что ответ был очевиден и потому что мне нужно было другое.","Зачем он остался, я не спросила."),
("Кайр помолчал ровно столько, чтобы я успела услышать собственную фразу со стороны.","Кайр помолчал. Я успела услышать собственную фразу со стороны."),
("День был серый и тихий, с той весенней сыростью, которая не дождь, но и не сухо, и от которой одежда за колокол становится тяжёлой.","День был серый и тихий, с весенней сыростью, от которой одежда за колокол становится тяжёлой."),
("потому что доски были заказаны в шесть саженей, а привезли в пять с половиной, и приёмщик говорил, что это те же доски, только короче, а возчик говорил, что тогда пусть приёмщик сам стоит на них четвёртым.",
 "потому что доски были заказаны в шесть саженей, а привезли в пять с половиной. Приёмщик говорил, что это те же доски, только короче; возчик — что тогда пусть приёмщик сам стоит на них четвёртым."),
("У третьего склада женщины мыли ступени щётками на длинных ручках и мыли их вниз, от двери к воде, грязная вода уходила прямо в залив, и никого это не смущало.","У третьего склада женщины мыли ступени щётками на длинных ручках, вниз, от двери к воде; грязная вода уходила прямо в залив."),
("— Окна второго этажа, — сказал Кайр негромко. — Пять по фасаду.\n\n— Шесть. Крайнее заложено, но рама осталась.\n\n— Значит, шесть комнат.\n\n— Пять комнат и коридор. Крайнее окно коридорное, там ставня открыта внутрь, а в комнатах наружу.",
 "— Окна второго этажа, — сказал Кайр негромко. — Шесть по фасаду, крайнее заложено.\n\n— У крайнего ставня открыта внутрь, у остальных наружу. Значит, коридор. Пять комнат."),
("— Я тут вырос, Сильвия. Я половину квартала знаю по имени, и половина квартала знает меня. — Упрёка в голосе не было, и от этого стало неудобнее. — Со мной здесь","— Я тут вырос, Сильвия. Я половину квартала знаю по имени, и половина квартала знает меня. Со мной здесь"),
("Об этом я не подумала.\n\nЧеловек рядом со мной в расчёт не входил вовсе. Он тут свой, а свой в квартале виден лучше чужого.","Об этом я не подумала."),
("а если наступить не туда, то и шум, которого хватит на весь квартал. Лучше и не надо.","а если наступить не туда, то и шум, которого хватит на весь квартал."),
("Кайр посмотрел на щель, потом на меня, и ничего не сказал. Я решила, что он подумал то же, что и я: если придётся уходить через щель, значит, что-то уже пошло не так.","Кайр посмотрел на щель, потом на меня, и ничего не сказал."),
("Кайр сидел рядом и строгал ножом щепку. Правильно делал: двое, которые просто сидят, заметнее двоих, из которых один занят руками.","Кайр сидел рядом и строгал ножом щепку."),
("Я строгала минут десять. Руки заняты, глаза свободны, голова при этом работает сама — и выдаёт, например, что сидим мы тут уже почти колокол и делаем вид, что каждый при деле, и что на двор я смотрю слишком прямо.",
 "Я строгала минут десять. Руки заняты, глаза свободны, и голова сама выдаёт: сидим мы тут почти колокол, и на двор я смотрю слишком прямо."),
("Кайр спросил, много ли лодок ставят на подпорки в этом году, и мужик сказал, что меньше, чем в прошлом, и стал перечислять, кто ушёл на артельные и кто продал свою, и в перечислении было четыре имени, и одно из них — Хенрик из «Ржавого якоря».",
 "Кайр спросил, много ли лодок ставят на подпорки в этом году. Мужик сказал, что меньше, чем в прошлом, и стал перечислять, кто ушёл на артельные, кто продал свою. Имён было четыре, одно из них — Хенрик из «Ржавого якоря»."),
("Я запомнила и это. Про бочки я подумаю потом; комнаты же объясняли многое: человек, у которого дела идут вниз, сдаёт комнату всякому, кто платит вперёд, и не задаёт вопросов. Поэтому Гар Вельт живёт именно здесь.","Я запомнила и это."),
("Мы отошли и сели дальше, на штабель, откуда двор просматривался хуже, но всё-таки просматривался, и я поняла, что потеряла лучшее место и не могу вернуть его до вечера.","Мы отошли и сели дальше, на штабель. Двор оттуда просматривался хуже. Лучшее место я потеряла до вечера."),
("Больше он про это не спрашивал.\n\nУ рыбного навеса","У рыбного навеса"),
("Тот кивнул, не особо удивившись: в этом квартале знакомство за дерево заводится дешевле всего.","Тот кивнул, не особо удивившись."),
("Собака была Мадсова и без цепи, и про неё мне говорили вчера, под навесом, и я это помнила: к Мадсу во двор не суйтесь. Вспомнила я об этом уже во дворе.","Собака была Мадсова, без цепи. Про неё мне говорили вчера под навесом: к Мадсу во двор не суйтесь. Вспомнила я об этом уже во дворе."),
("Я ответила что-то дежурное, и он потерял к нам интерес — что, собственно, и требовалось. Двор «Якоря» отсюда просматривался так, как не просматривался ни с одной лодки, — но смотреть долго было нельзя, и мы вернулись к воде.",
 "Я ответила что-то дежурное, и он потерял к нам интерес. Двор «Якоря» отсюда просматривался лучше, чем с любой лодки, но смотреть долго было нельзя, и мы вернулись к воде."),
("Сказано было спокойно и без мысли за спиной, и мне вдруг стало досадно, что мы ни разу так не сидели до этого.","Мне вдруг стало досадно, что мы ни разу так не сидели."),
("— Он не запнулся ни разу: всё это было посчитано до меня. — Подъёмных","— Подъёмных"),
("Я вообще, кажется, не замечала ничего из того, что эти три года считали за меня другие люди. У меня в голове помещались двадцать восемь человек на курсе, одна пустая строка и я, а остальное шло по краю, как улица за окном.",
 "Я вообще, кажется, не замечала ничего из того, что эти три года считали за меня другие люди."),
("Стоять так может человек, который думает. Или тот, кому некуда деться до темноты.\n\n",""),
("— Идёт и кладёт вторую. — Кайр смотрел, как Вельт входит в ворота. — Тут ведь как: если положил и вышло, то на будущий год положишь опять. А если не вышло, скажешь, что мало было.","— Идёт и кладёт вторую. — Кайр смотрел, как Вельт входит в ворота."),
("Он провёл большим пальцем по срезу и больше ничего не спросил.\n\n",""),
("— Дали. Второй год стоит на четвёртом причале, постоянно, с записью в книге. Раньше он о таком и не просил. — Хельга расправила тряпку и сложила её на край стойки. — Дали и держат. Тем и держат, что дали.",
 "— Дали. Второй год стоит на четвёртом причале, постоянно, с записью в книге. Раньше он о таком и не просил. — Хельга расправила тряпку и сложила её на край стойки. — Дали и держат."),
("Хельга стояла за стойкой и разговаривала с рыжим, и на меня не смотрела, и было совершенно ясно, что смотреть она не будет до тех пор, пока я не выйду.","Хельга стояла за стойкой, разговаривала с рыжим и на меня не смотрела."),
("Она вынырнула из-под фонаря с корзиной на локте, увидела меня и остановилась так, будто её поймали.","Она вынырнула из-под фонаря с корзиной на локте, увидела меня и остановилась."),
("Она перестала вырываться и стояла, глядя в сторону с таким лицом, будто её заставляют, и руки не забирала дольше, чем нужно.","Она перестала вырываться и стояла, глядя в сторону. Руки не забирала."),
("— У меня метка не встаёт третий год.\n\nАгнис остановилась.\n\n— Это другое.\n\n— Это ровно то же самое, только у меня без Ольсы.\n\nОна посмотрела на меня снизу вверх и подумала, и я видела, как она решает, спорить или нет, и как выбирает третье.",
 "— У меня метка не встаёт третий год.\n\nАгнис остановилась.\n\n— Это другое.\n\n— Не другое.\n\nОна посмотрела на меня снизу вверх и подумала."),
("Она разломила, и, как всегда, вышло криво, и, как всегда, большую половину она сунула мне.","Она разломила. Вышло криво, как всегда, и большую половину она, как всегда, сунула мне."),
("Он был холодный, как и вчерашний, лук отдал влагу в тесто, и от этого стало только лучше. Агнис ела и мычала: она с детства ест так, будто еду сейчас отберут, и мать всю жизнь пытается это исправить, без всякого успеха.",
 "Он был холодный, как и вчерашний, лук отдал влагу в тесто. Агнис ела и мычала: она с детства ест так, будто еду сейчас отберут, и мать всю жизнь пытается это исправить."),
("Мы с Ольсой шли к ней, она у воды живёт, и Ольса спросила, кто это, и я сказала «сестра», и она сказала «а он», и я сказала, что не знаю.","Мы с Ольсой шли к ней, она у воды живёт. Ольса спросила, кто это, я сказала «сестра», она сказала «а он», я сказала, что не знаю."),
("Серьёзность была полная, и я не нашлась, что ответить.","Я не нашлась, что ответить."),
("Мне хватило бы одной фразы. «Через четыре колокола я полезу в комнату на втором этаже „Ржавого якоря“». Я составила её целиком, вплоть до порядка слов, и не сказала. Не из осторожности. У неё завтра третья попытка, а если бы я сказала, она просидела бы всю ночь на кровати, глядя в стену, и назавтра перепутала бы порядок в четвёртый раз.\n\nТак я себе это объяснила, и объяснение было хорошее, и я даже не сразу заметила, какое оно удобное.",
 "Мне хватило бы одной фразы. «Через четыре колокола я полезу в комнату на втором этаже „Ржавого якоря“». Я составила её целиком, вплоть до порядка слов, и не сказала. У неё завтра третья попытка; она просидела бы всю ночь на кровати, глядя в стену.\n\nТак я себе это объяснила. Объяснение было удобное."),
("У ворот общежития Агнис остановилась и посмотрела на меня снизу вверх, как умеет только она.","У ворот общежития Агнис остановилась и посмотрела на меня снизу вверх."),
("В кармане у меня пока ничего чужого не было. Я подумала, что это ненадолго, и мысль была честная, только вслух её не скажешь.","В кармане у меня пока ничего чужого не было."),
("— Угу, — сказала Агнис, и сказала это голосом Хельги, и, судя по лицу, сама не заметила. — Ты когда врёшь","— Угу, — сказала Агнис голосом Хельги и сама этого не заметила. — Ты когда врёшь"),
("Она забрала у меня корзину, поправила мне платок на шее — коротко, двумя пальцами, как поправляют ребёнку, — и пошла вниз, и на третьем шаге обернулась.","Она забрала у меня корзину, поправила мне платок на шее — коротко, двумя пальцами, как поправляют ребёнку, — и пошла вниз. На третьем шаге обернулась."),
("Я осталась стоять у ворот со склянкой в руке и там развернула тряпицу и посмотрела, что там.","Я осталась стоять у ворот со склянкой в руке, развернула тряпицу и посмотрела, что там."),
("Брать надо было мало. Всё, что берёшь сверх нужного, потом мешает.","Брать надо было мало."),
("Так можно было перекладывать до утра. Я замечала за собой это свойство: перед делом руки начинают искать, что бы ещё уточнить, и если им не помешать, они будут уточнять бесконечно.","Так можно было перекладывать до утра."),
("Нож, свайка, войлок, тряпка, бечёвка, перчатки. Шесть предметов, и каждый работает потому, что он предмет. Ни один из них не спрашивает, отзовётся ли во мне что-нибудь магическое.","Нож, свайка, войлок, тряпка, бечёвка, перчатки."),
("Я решила, что зашью, когда вернусь.\n\nТак я себе и сказала — «когда вернусь», спокойно и по-деловому, будто речь о мелком долге, который отдадут в следующую декаду.","Я решила, что зашью, когда вернусь."),
("У неё третью декаду течёт с потолка после дождей, и она подставила таз, и капает так ровно, что можно сверять счёт.","У неё третью декаду течёт с потолка после дождей; капает так ровно, что можно сверять счёт."),
("Я насыпала ему рыбы с запасом, налила воды и подвинула кувшин от края, и всё это заняло больше времени, чем требовалось: руки хотели ещё что-нибудь делать.","Я насыпала ему рыбы с запасом, налила воды, подвинула кувшин от края. Руки хотели ещё что-нибудь делать."),
("И пошла вниз. Запах остался, и я сомневалась, что он собирается подчиняться.","И пошла вниз."),
("Брать её было незачем: в такой работе на ожоги не рассчитывают. Там либо обошлось, либо уже неважно.","Брать её было незачем."),
("Весь день у меня внутри стояло то, что стоит перед делом, и весь день оно мешало. Сейчас, перед самым делом, оно ушло целиком. Руки были ровные, в голове было пусто и по-рабочему, и я знала по прошлым разам, что за это придётся заплатить, только позже.",
 "Весь день у меня внутри стояло то, что стоит перед делом. Сейчас оно ушло. Руки были ровные, в голове пусто и по-рабочему."),
("Хозяин стоял за стойкой и вытирал кружки тряпкой, которая делала их только грязнее.","Хозяин стоял за стойкой и вытирал кружки."),
("Про ожидание в наставлениях написано одной строкой: «выдержать необходимое время, не привлекая внимания». Писавший её, похоже, ни разу столько не сидел.","Про ожидание в наставлениях написано одной строкой: «выдержать необходимое время, не привлекая внимания»."),
("Мужик за соседним столом заснул сидя и начал заваливаться, товарищ подхватил его за плечо и посадил обратно, и оба этого даже не заметили.","Мужик за соседним столом заснул сидя и начал заваливаться. Товарищ подхватил его за плечо и посадил обратно; оба этого даже не заметили."),
("Он покивал так, будто я ответила по существу.","Он покивал."),
("Мужик засмеялся, и смех у него был неплохой, и мне от этого стало хуже, а не лучше.","Мужик засмеялся. Смех у него был неплохой, и от этого стало хуже."),
("Я взяла её и отпила, поздно и без всякого толку, и поставила обратно.","Я взяла её, отпила, поздно и без толку, поставила обратно."),
("Потом разговор ушёл в сторону, как уходит всякий разговор за полночь.","Потом разговор ушёл в сторону."),
("Шаги прошли по коридору и вернулись, и кто-то закрыл дверь.","Шаги прошли по коридору, вернулись, кто-то закрыл дверь."),
("Дальше я шла в темноте, касаясь стены ладонью и считая двери, и думала о том, что вся ночь держалась на одной ставне, увиденной с сорока шагов, и что проверить это было нечем до самой этой минуты.",
 "Дальше я шла в темноте, касаясь стены ладонью и считая двери. Вся ночь держалась на одной ставне, увиденной с сорока шагов, и проверить это было нечем до самой этой минуты."),
("Вынимать пришлось медленно, потому что бумага шуршит, и на это ушло, наверное, полминуты, хотя мне показалось, что дольше, и к концу этой полуминуты пальцы стали неточными.",
 "Вынимать пришлось медленно, потому что бумага шуршит. Ушло, наверное, полминуты, и к концу пальцы стали неточными."),
("Так бывает на холоде, когда рука ещё слушается, а мелкое ей уже не даётся, и я держала конверт двумя и вела его вверх по подкладке и очень отчётливо понимала, что уронить его сейчас проще, чем донести.",
 "Так бывает на холоде, когда рука ещё слушается, а мелкое ей уже не даётся. Я держала конверт двумя пальцами, вела его вверх по подкладке и очень отчётливо понимала: уронить сейчас проще, чем донести."),
("Я знала за собой это по учениям и знала, что это ощущение проходит вскоре после.\n\n",""),
("Любопытство было ни при чём. Мне нужно было убедиться, что я взяла то, потому что второй попытки не будет, и если бы в кармане лежали чужие письма или расписки, я узнала бы об этом только у Вардена, и было уже поздно.",
 "Мне нужно было убедиться, что взяла то: второй попытки не будет."),
("Вместе с ним оборвалось и моё: я стояла на четвёртом шаге, с поднятой ногой, и не дышала, и не могла начать.","Вместе с ним оборвалось и моё: я стояла на четвёртом шаге, с поднятой ногой, не дышала и не могла начать."),
("Днём они стояли открытыми, и вечером тоже, и я видела это своими глазами четыре раза. На ночь их закладывают брусом. Мне сказали это вчера, под навесом, вслух, между собакой Мадса и моим разошедшимся рукавом, и я тогда услышала в этом объяснение чужого характера.",
 "Днём они стояли открытыми, вечером тоже, я видела это своими глазами четыре раза. На ночь их закладывают брусом. Мне сказали это вчера, под навесом, вслух, между собакой Мадса и моим разошедшимся рукавом. Я тогда не слушала."),
("Ночью бежать по портовому кварталу — это бежать по памяти. Смотреть под ноги бесполезно, там всё равно ничего не видно. Ты помнишь, что на Малой Гончарной у третьего дома выломана плита, что на спуске к воде лежат мостки и они скользкие, что за углом бочки.\n\nЯ помнила. Днём мы обошли здесь всё, и не по одному разу.",
 "Ночью по портовому кварталу бегут по памяти: на Малой Гончарной у третьего дома выломана плита, на спуске к воде мостки скользкие, за углом бочки. Я помнила. Днём мы обошли здесь всё."),
("Они берегли дыхание и не кричали, и это меня не устраивало: кричащий человек бежит медленнее.","Они берегли дыхание и не кричали."),
("Он бежал широко и не пытался кричать, и по звуку шагов было понятно, что бежит он лучше меня.","Он бежал широко, и по звуку шагов было понятно, что бежит он лучше меня."),
("Я услышала два слова, короткие, сказанные на бегу и оттого рваные, и увидела, как впереди меня по стене прошла полоса света","Я услышала два слова, короткие, сказанные на бегу и оттого рваные. Впереди по стене прошла полоса света"),
("Свет погас через десяток шагов. Держать его на бегу трудно, а бежать и держать — это уже работа для двоих.","Свет погас через десяток шагов."),
("Нож был при мне. Пустить его в ход означало превратить кражу документов в такое дело, за которое дают уже не четыре года. Оставить в ножнах означало отдать конверт и всё остальное вместе с ним.","Нож был при мне. Пустить его в ход — это уже не четыре года. Оставить — отдать конверт."),
("Оттуда есть проход между складами, из прохода — на площадь, а с площади три улицы, и ночью на ней стоят повозки, между которыми теряется кто угодно.","Оттуда есть проход между складами, из прохода — на площадь, а на площади ночью стоят повозки, между которыми теряется кто угодно."),
("Каркас собирают из лёгких брусьев, скрепляя их временными вязками, и внутри он похож на скелет с рёбрами.","Каркас собирают из лёгких брусьев на временных вязках; внутри он похож на скелет с рёбрами."),
("Внутри пахло свежим деревом и смолой, и было темнее, чем снаружи: брусья закрывали и без того чёрное небо.","Внутри пахло свежим деревом и смолой. Было темнее, чем снаружи: брусья закрывали и без того чёрное небо."),
("Полотно пошло вниз тяжело и медленно, как идёт вниз всё большое, и накрыло каркас изнутри, и человека в нём тоже.","Полотно пошло вниз тяжело и медленно, накрыло каркас изнутри и человека в нём."),
("Я стояла, держась за борт повозки, и меня трясло крупно, и остановить это волей было нельзя.","Я стояла, держась за борт повозки. Трясло крупно, остановить это волей было нельзя."),
("Нижние ворота филиала на ночь запирают, и это я знала с первого курса, как знают все, кто хоть раз возвращался позже отбоя. Не запирают калитку у хозяйственного двора, потому что через неё до рассвета возят дрова и воду, и потому что сторож всё равно там сидит.",
 "Нижние ворота филиала на ночь запирают. Не запирают калитку у хозяйственного двора: через неё до рассвета возят дрова и воду, и сторож всё равно там сидит."),
("Варден развязал бечёвку, вынул листы и стал их просматривать, и просматривал долго, лист за листом, останавливаясь на подписях.","Варден развязал бечёвку, вынул листы и стал просматривать — долго, лист за листом, останавливаясь на подписях."),
("— Ставят где придётся, — сказал он и стал завязывать бечёвку, завязывал её тем же узлом, каким она была завязана, когда я вынимала конверт из чужого кармана, а я стояла и смотрела на его пальцы. — Что у вас с лицом?",
 "— Ставят где придётся. — Он стал завязывать бечёвку тем же узлом, каким она была завязана в чужом кармане. Я смотрела на его пальцы. — Что у вас с лицом?"),
("Он положил конверт на стол и посмотрел на меня так же, как позавчера смотрел на мою тетрадь.","Он положил конверт на стол и посмотрел на меня."),
("Потом спросил про дверь, и я рассказала: не заперта, ключ висел за стойкой всю ночь, и доску с ключами я проверяла вечером, пока сидела, — один ключ провисел на месте с одиннадцатого колокола до половины второго.",
 "Потом спросил про дверь, и я рассказала: не заперта, ключ висел за стойкой всю ночь; доску я проверяла вечером — один ключ провисел на месте с одиннадцатого колокола до половины второго."),
("— Запишите, когда придёте. Не для меня. Для себя.","— Запишите, когда придёте."),
("Он не спросил, вскрывала ли я конверт. Он взял его завязанным, развязал сам — и не спросил, был ли он завязан, когда я его брала, и не смотрела ли я внутрь. Хотя это первое, что спрашивают. Хотя от этого зависит, что именно я теперь знаю.\n\nЯ стояла и думала об этом, и он смотрел на меня. По его лицу нельзя было понять, знает ли он, о чём я думаю.",
 "Он не спросил, вскрывала ли я конверт. Это первое, что спрашивают.\n\nЯ стояла и думала об этом, и он смотрел на меня."),
("Монеты были холодные и лежали в ладони тяжелее, чем должны лежать три серебряных.","Монеты были холодные."),
("Я спустилась во двор, села на ту же нижнюю ступень, на которой позавчера ждала седьмого колокола, и посидела немного. До общежития отсюда идти столько, что не успеваешь ни о чём додумать, — я мерила это много раз и всегда одинаково, — и я пока не шла.",
 "Я спустилась во двор, села на ту же нижнюю ступень, на которой позавчера ждала седьмого колокола, и посидела немного."),
("Мы поравнялись на площадке, и она посмотрела на меня ровно столько, сколько нужно, чтобы увидеть всё.","Мы поравнялись на площадке, и она посмотрела на меня."),
("И прошла мимо, и на четвёртой ступени вниз, не оборачиваясь, добавила:","И прошла мимо. На четвёртой ступени вниз, не оборачиваясь, добавила:"),
("Она предлагала это уже не впервые и каждый раз одинаково легко, потому что для неё это и правда полминуты. Отказаться нормальным способом было нельзя: любая причина, кроме настоящей, выглядела бы глупо, а настоящая заключалась в том, что я не хочу заходить в свою комнату с человеком, который сделает там за полминуты то, чего я не сделаю никогда.",
 "Она предлагала это не впервые, и для неё это правда полминуты. Любая причина отказаться, кроме настоящей, выглядела бы глупо. Настоящая: я не хочу заходить в свою комнату с человеком, который сделает там за полминуты то, чего я не сделаю никогда."),
("Он спрыгнул и потёрся о ногу, и я села прямо на пол: до кровати оставалось два шага, а сил на них уже не было.","Он спрыгнул и потёрся о ногу. Я села прямо на пол: до кровати оставалось два шага, а сил на них не было."),
("Конверта больше не было. Он лежал в ящике стола в кабинете 2-14, запертый на ключ, и в нём лежал лист с маленькой серой печатью у сгиба.","Конверт лежал в ящике стола в кабинете 2-14, запертый на ключ, и в нём — лист с маленькой серой печатью у сгиба."),
]
for a,b in R: rep(a,b)
